import{_ as s,o as t,c as o,a2 as r}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Projects and organizing sessions","description":"","frontmatter":{},"headers":[],"relativePath":"projects.md","filePath":"projects.md","lastUpdated":1793867462000}'),n={name:"projects.md"};function a(i,e,h,d,c,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-and-organizing-sessions" tabindex="-1">Projects and organizing sessions <a class="header-anchor" href="#projects-and-organizing-sessions" aria-label="Permalink to &quot;Projects and organizing sessions&quot;">​</a></h1><p>Projects group your sessions in the sidebar. A project also decides which stored secrets its sessions receive, lets its sessions read each other&#39;s files, and makes its sessions a fleet that can find and message each other. This page covers creating projects, ordering and moving sessions, and finding them again.</p><p><strong>Edition:</strong> Community · <strong>Who:</strong> the project owner. Sharing a whole project with other people is an Enterprise feature, see <a href="/docs/sharing#share-a-whole-project">Sharing</a>.</p><h2 id="create-a-project" tabindex="-1">Create a project <a class="header-anchor" href="#create-a-project" aria-label="Permalink to &quot;Create a project&quot;">​</a></h2><ul><li>In the sidebar, click <strong>+ New project</strong> and enter a name.</li><li>Or, while creating a session, choose <strong>Project → New project…</strong> in the <strong>New session</strong> dialog and enter a <strong>Project name</strong>. The project is created with no colour and no selected secrets. If the session itself then fails to start, the project is kept and stays selected, so a retry does not create a second project.</li></ul><p>Project names must be unique per owner, ignoring case.</p><h2 id="project-controls" tabindex="-1">Project controls <a class="header-anchor" href="#project-controls" aria-label="Permalink to &quot;Project controls&quot;">​</a></h2><p>Each project header in the sidebar has these controls:</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>↑ / ↓</strong> (Move up, Move down)</td><td>Change the order of the projects</td></tr><tr><td><strong>✎</strong> (Rename)</td><td>Rename the project</td></tr><tr><td><strong>●</strong> (Color)</td><td>Pick a colour for the project marker</td></tr><tr><td><strong>⚿</strong> (Secrets)</td><td>Choose which stored secrets the project&#39;s sessions receive, see Secrets</td></tr><tr><td><strong>⇪</strong> (Share project)</td><td>Share the project with a user or group (Enterprise), see <a href="/docs/sharing">Sharing</a></td></tr><tr><td><strong>×</strong> (Delete project)</td><td>Delete the project; its sessions stay, ungrouped</td></tr></tbody></table><p>Click the project name to collapse or expand it.</p><h2 id="what-a-project-gives-its-sessions" tabindex="-1">What a project gives its sessions <a class="header-anchor" href="#what-a-project-gives-its-sessions" aria-label="Permalink to &quot;What a project gives its sessions&quot;">​</a></h2><ul><li><strong>Secrets:</strong> the project&#39;s secret selection is the default for every session in it and for the child sessions they start in it. A session can narrow the selection or receive extra grants of its own. See Secrets.</li><li><strong>Files:</strong> sessions of one project can list and fetch each other&#39;s files. See Session files.</li><li><strong>A fleet:</strong> sessions of one project can list each other and send each other messages with the built-in tools. The session <strong>Description</strong> tells the other agents what a session is for. See Built-in tools inside a session.</li></ul><h2 id="reorder-sessions" tabindex="-1">Reorder sessions <a class="header-anchor" href="#reorder-sessions" aria-label="Permalink to &quot;Reorder sessions&quot;">​</a></h2><p>Drag a session in the sidebar and drop it before another session to change the order. The order is saved on the server for your account, so it is the same on every device, and new sessions follow it.</p><p>Without a mouse, use the <strong>Organize session</strong> button on a session row: it offers <strong>Move session up</strong>, <strong>Move session down</strong> and <strong>Move to project</strong> as ordinary buttons and a dialog, which works with the keyboard and on touch screens.</p><p>Only your own sessions can be reordered or moved. Sessions shared with you stay in their own group.</p><h2 id="move-a-session-to-another-project" tabindex="-1">Move a session to another project <a class="header-anchor" href="#move-a-session-to-another-project" aria-label="Permalink to &quot;Move a session to another project&quot;">​</a></h2><p>Drop a session on a project header, or use <strong>Organize session → Move to project</strong>. The dialog says what changes before you confirm:</p><ul><li><strong>Secrets:</strong> how many project secrets are removed and added. A session whose selection you narrowed stays narrowed, and grants made for this session stay with it.</li><li><strong>Files:</strong> access to the old project&#39;s files ends and the destination project&#39;s files become available at once. The session&#39;s own files stay with it.</li><li><strong>Settings:</strong> the destination project&#39;s secrets and settings apply on the next start.</li></ul><p>A <strong>running session is paused first</strong>, after you confirm. Environment variables cannot be removed from a running process, so it would otherwise keep the old project&#39;s secrets next to the new project&#39;s files. Resume it afterwards to load the new configuration. If the move fails after the pause, the session stays paused and you can retry.</p><h3 id="scheduled-sessions" tabindex="-1">Scheduled sessions <a class="header-anchor" href="#scheduled-sessions" aria-label="Permalink to &quot;Scheduled sessions&quot;">​</a></h3><p>A scheduled session moves without pausing. Its schedule is suspended while the move rewrites it, then continues unchanged; the next run starts with the destination project&#39;s secrets only, and earlier runs keep their history.</p><p>If a run is in progress, the move is refused at first and the dialog offers <strong>Stop run and move</strong>. Stopping ends that run, and its unfinished work is lost. If a move stops part-way, the sidebar shows <em>Move unfinished · schedule paused</em> and the dialog offers <strong>Finish move</strong>; no run starts until the move is finished.</p><h2 id="find-sessions" tabindex="-1">Find sessions <a class="header-anchor" href="#find-sessions" aria-label="Permalink to &quot;Find sessions&quot;">​</a></h2><ul><li><strong>Find a session…</strong> in the top bar searches your sessions as you type.</li><li>The <strong>Sessions</strong> page groups the list by <strong>Project</strong>, <strong>Repository</strong>, <strong>Status</strong> or <strong>None</strong>, and filters it by <strong>All</strong>, <strong>Running</strong>, <strong>Question open</strong>, <strong>Waiting</strong>, <strong>Scheduled</strong>, <strong>Paused</strong>, <strong>Done</strong> or <strong>Failed</strong>.</li><li>The home page lists what <strong>needs you</strong>: sessions with an open question or waiting for your reply.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/docs/sessions">Sessions</a></li><li>Secrets</li><li><a href="/docs/sharing">Sharing</a> (Enterprise)</li></ul>',27)])])}const u=s(n,[["render",a]]);export{p as __pageData,u as default};
